
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_dk87_r2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_dk87_r2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.311519670574008e+00, -4.230551612293699e+00, -4.117224314868145e+00, -3.960497106545829e+00, -3.747449708284550e+00, -3.464879403175281e+00, -3.102911475962344e+00, -2.661045671218596e+00, -2.155002272265251e+00, -1.618337089796533e+00, -1.091812201144568e+00, -7.102619535605098e-01, -6.020670159925920e-01, -5.040663299413248e-01, -3.732163221171784e-01, -2.439037227029769e-01, -1.444360387193654e-01, -8.509948152358310e-02, -5.910199948981686e-02, -5.016676801001945e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


